/**
 * GUIA RÁPIDO — OS 4 MISTOS DO ÍCONE DO LOTE (pasto com machos e fêmeas)
 *
 * 1. COR, BORDA E TAMANHO: constantes logo abaixo.
 *    COR_MISTO: cor do ícone quando o pasto mistura sexos (só no mapa; nos detalhes cada
 *    linha mostra o animal dela, na cor do sexo dela).
 *    BORDA_VACA_MISTO: borda branca da vaca DENTRO de um ícone com mais de um animal, em
 *    % da largura do card. Vale só para os caminhos marcados com data-vaca="1".
 *    A fêmea "Maior que 36 meses" sozinha usa BORDA_PADRAO (animais.js).
 *    TAMANHO_MISTO: largura do misto em fração da largura útil do card.
 *    SOBREPOSICAO_COMPOSICAO: quando não há misto declarado, o código põe os dois animais
 *    lado a lado; esta fração diz quanto o animal da frente cobre o de trás.
 * 2. NOME DE EXIBIÇÃO: ROTULO_MISTO. O proprietário ainda não escolheu os nomes; por ora
 *    vale a chave (misto1 … misto4). Para trocar, mude só a linha do misto.
 * 3. TABELA DE MISTOS: TABELA_MISTOS diz que animais formam cada misto e a prioridade
 *    (menor número ganha). tipo_regra MINIMA: o misto vale quando o pasto TEM esses
 *    animais, podendo ter outros junto.
 * 4. DESENHOS: MISTOS_SVG traz os arquivos do proprietário, como vieram.
 * Instruções completas: README.md nesta pasta.
 */

// COR — EDITE AQUI.
export const COR_MISTO = '#ff0000'; // Pasto com machos e fêmeas, só no marcador do mapa.

// BORDA BRANCA DA VACA DENTRO DE UM ÍCONE COM MAIS DE UM ANIMAL, em % da largura do card.
export const BORDA_VACA_MISTO = 5;

// TAMANHO DO MISTO: fração da largura útil do card.
export const TAMANHO_MISTO = 1.00;

// COMPOSIÇÃO AUTOMÁTICA (sem misto declarado): quanto o animal da frente cobre o de trás,
// em fração da largura do animal da frente.
export const SOBREPOSICAO_COMPOSICAO = 0.35;

// NOME DE EXIBIÇÃO DE CADA MISTO (provisório: a própria chave). Troque uma linha por misto.
export const ROTULO_MISTO = Object.freeze({
  misto1: 'misto1',
  misto2: 'misto2',
  misto3: 'misto3',
  misto4: 'misto4',
});

// TABELA DE MISTOS: composição (sexo-faixa, como em ANIMAIS_SVG) e prioridade.
export const TABELA_MISTOS = Object.freeze([
  Object.freeze({ chave: 'misto1', composicao: Object.freeze(['macho-37-mais', 'femea-37-mais', 'macho-0-8']), prioridade: 10, tipo_regra: 'MINIMA' }),
  Object.freeze({ chave: 'misto2', composicao: Object.freeze(['macho-37-mais', 'femea-37-mais']), prioridade: 20, tipo_regra: 'MINIMA' }),
  Object.freeze({ chave: 'misto3', composicao: Object.freeze(['macho-37-mais', 'macho-0-8']), prioridade: 20, tipo_regra: 'MINIMA' }),
  Object.freeze({ chave: 'misto4', composicao: Object.freeze(['femea-37-mais', 'macho-0-8']), prioridade: 20, tipo_regra: 'MINIMA' }),
]);

